// Local counterpart of the Lore spec-coverage job that consumes these links: a `([validated by](...))`
// link only counts when it sits in its statement's trailing parenthetical, so a
// link anywhere else is reported here rather than silently dropped there.
// Segmentation and link parsing come from the published spec domain
// of @re-cinq/eslint-plugin-re-lint (AGENTS.md § Spec Test Links).

import { readFileSync, readdirSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import process from "node:process";
import { findMisplacedCoverageLinks } from "@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js";
import { segmentStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-segment.js";
import { root } from "./lib/repo-root.mjs";

const USAGE =
  "usage: check-spec-links.mjs [--json] [spec-path ...]\n" +
  "spec paths resolve against the repo root, not the working directory; an absolute path is taken as given";

const args = process.argv.slice(2);
const flags = args.filter((arg) => arg.startsWith("--"));
const specArgs = args.filter((arg) => !arg.startsWith("--"));

for (const flag of flags) {
  if (flag === "--json") {
    continue;
  }
  process.stderr.write(`${USAGE}\n`);
  process.exit(2);
}

const asJson = flags.includes("--json");

const discoverSpecs = () => {
  const specsDir = join(root, "specs");
  const slugs = readdirSync(specsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  return [...slugs.map((slug) => `specs/${slug}/spec.md`), ".specify/spec.md"];
};

const specPaths =
  specArgs.length > 0
    ? specArgs.map((path) => relative(root, resolve(root, path)))
    : discoverSpecs();

const readSpec = (specPath) => {
  try {
    return readFileSync(join(root, specPath), "utf8");
  } catch (error) {
    process.stderr.write(`cannot read spec ${specPath}: ${error.message}\n`);
    process.exit(2);
  }
};

const findings = [];
const specsWithFindings = new Set();
let statementsScanned = 0;

for (const specPath of specPaths) {
  const content = readSpec(specPath);

  for (const statement of segmentStatements(content)) {
    statementsScanned += 1;

    for (const link of findMisplacedCoverageLinks(statement.text)) {
      findings.push({
        spec: specPath,
        line: statement.line ?? null,
        path: link.path,
        anchorLine: link.line,
        label: link.label,
        statement: statement.text,
      });
      specsWithFindings.add(specPath);
    }
  }
}

const reportLines = () => {
  const lines = findings.map((finding) => {
    const anchor = finding.anchorLine === null ? "" : `#L${finding.anchorLine}`;
    const line = finding.line ?? "?";

    return `${finding.spec}:${line}: ${finding.path}${anchor} cited outside the statement's trailing parenthetical`;
  });

  lines.push(
    `misplaced: ${findings.length} across ${specsWithFindings.size} specs (${statementsScanned} statements scanned)`
  );

  return lines;
};

// process.exitCode, not process.exit: exiting truncates a large stdout write
// to a pipe.
process.exitCode = findings.length > 0 ? 1 : 0;
process.stdout.write(
  asJson ? `${JSON.stringify(findings, null, 2)}\n` : `${reportLines().join("\n")}\n`
);
name: CI

on:
  pull_request:
  push:
    branches: [main]
  # Manual runs: re-checking a branch against a moved main, or confirming a gate after
  # changing one, without pushing an empty commit.
  workflow_dispatch:
  # An advisory published after a merge is invisible until someone opens a pull request, and this
  # repository can go days without one. Monday 07:00 UTC; only `build-chain` answers it.
  schedule:
    - cron: '0 7 * * 1'

# Every job here only reads the checkout; the repo default is write.
permissions:
  contents: read

# A newer push to the same branch supersedes an in-flight run. main is exempt:
# every commit there should have its own recorded result.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: ${{ github.ref != 'refs/heads/main' }}

jobs:
  verify:
    name: Verify
    # The scheduled run exists for the dependency audit; re-running the suite on an unchanged
    # tree every Monday would report nothing new.
    if: github.event_name != 'schedule'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
          # Full history, not for this job but for the spec anchor check below:
          # it resolves cited content from
          # origin/main, which a shallow clone cannot serve.
          fetch-depth: 0

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      # --ignore-scripts so `prepare` does not build on install: what a lifecycle script
      # runs is out of this workflow's control, and the Build step below is where a broken
      # compile should be reported. Type check catches it earlier still.
      - name: Install
        run: npm ci --ignore-scripts

      # Every `npm run` step below is one link of the `verify` script in
      # package.json, in the same order - scripts/verify-script.test.ts holds
      # the two together - and kept as separate steps so a red run names the
      # gate that failed rather than a single opaque command.
      - name: Type check
        run: npm run typecheck

      # example/ is outside tsconfig.json's rootDir, so nothing checked the one
      # file the README and the guide are written against.
      - name: Type check the example
        run: npm run typecheck:example

      - name: Lint (--max-warnings 0)
        run: npm run eslint

      # Reports, never blocks. The one rule it runs is `warn`, so the step exits
      # 0 on its own and carries no continue-on-error: a non-zero exit here now
      # means the config itself broke, and that should fail. Its findings render
      # as warning annotations rather than failures, which is what a report on a
      # passing check should look like.
      #
      # require-statement-links counts spec statements with no test behind them.
      # Most of what it reports needs a test written rather than a line changed,
      # so the count is meant to be visible on every run and to fall over time.
      # Its test-side mirror, require-spec-link, is satisfied and gates in the
      # Lint step above. Never add a rule here to escape a red gate -
      # eslint.config.backlog.mjs says what belongs.
      - name: Spec traceability backlog (report)
        run: npm run lint:backlog

      - name: Format check
        run: npm run prettier:check

      # Runs the whole suite and fails it on the committed coverage floor in
      # jest.config.js, so this is the test gate rather than an extra pass.
      - name: Test (with coverage floor)
        run: npm run test:coverage

      - name: Build

